// Processar e-mail recebido
const email = $json;

// Extrair informações básicas
const emailData = {
  id: email.uid || email.messageId,
  from: email.from?.value?.[0]?.address || email.from,
  to: email.to?.value?.[0]?.address || email.to,
  subject: email.subject,
  text: email.text,
  html: email.html,
  date: email.date,
  attachments: email.attachments || []
};

// Limpar e processar texto do e-mail
let textoLimpo = emailData.text || '';

// Remover assinaturas comuns
const assinaturas = [
  /--\s*\n[\s\S]*/,
  /Enviado do meu iPhone[\s\S]*/i,
  /Sent from my iPhone[\s\S]*/i,
  /\n\n>.*$/gm
];

for (const regex of assinaturas) {
  textoLimpo = textoLimpo.replace(regex, '');
}

// Remover quebras de linha excessivas
textoLimpo = textoLimpo.replace(/\n{3,}/g, '\n\n').trim();

// Detectar se é resposta ou e-mail novo
const isReply = emailData.subject.toLowerCase().includes('re:') || 
               emailData.subject.toLowerCase().includes('fwd:') ||
               textoLimpo.includes('>');

// Extrair informações de contato do corpo do e-mail
const telefoneRegex = /(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?(?:9\s?)?\d{4}[\s-]?\d{4}/g;
const telefones = textoLimpo.match(telefoneRegex) || [];

// Detectar intenção baseada no assunto e conteúdo
const assuntoLower = emailData.subject.toLowerCase();
const textoLower = textoLimpo.toLowerCase();

let intencao = 'geral';
if (assuntoLower.includes('venda') || textoLower.includes('vender') || textoLower.includes('proprietário')) {
  intencao = 'venda';
} else if (assuntoLower.includes('compra') || textoLower.includes('comprar') || textoLower.includes('adquirir')) {
  intencao = 'compra';
} else if (assuntoLower.includes('aluguel') || textoLower.includes('alugar') || textoLower.includes('locação')) {
  intencao = 'aluguel';
} else if (assuntoLower.includes('visita') || textoLower.includes('agendar') || textoLower.includes('conhecer')) {
  intencao = 'agendamento';
} else if (assuntoLower.includes('informação') || textoLower.includes('dúvida') || textoLower.includes('pergunta')) {
  intencao = 'informacao';
}

// Preparar dados para o orquestrador
const orchestratorPayload = {
  canal: 'email',
  from: emailData.from,
  email: emailData.from,
  telefone: telefones.length > 0 ? telefones[0].replace(/\D/g, '') : null,
  mensagem: textoLimpo,
  assunto: emailData.subject,
  timestamp: new Date(emailData.date).toISOString(),
  is_reply: isReply,
  intencao_detectada: intencao,
  dados_completos: {
    email_original: emailData,
    telefones_encontrados: telefones,
    attachments: emailData.attachments.map(att => ({
      filename: att.filename,
      contentType: att.contentType,
      size: att.size
    }))
  }
};

return {
  json: {
    type: 'new_email',
    processed_data: orchestratorPayload,
    raw_email: emailData
  }
};

// Preparar e-mail para envio
const dados = $json;

// Validar dados obrigatórios
if (!dados.to || !dados.message) {
  throw new Error('Campos obrigatórios: to, message');
}

// Preparar assunto
let assunto = dados.subject || 'Resposta da Imobiliária';

// Se for resposta, adicionar Re:
if (dados.is_reply && !assunto.toLowerCase().startsWith('re:')) {
  assunto = 'Re: ' + assunto;
}

// Preparar corpo do e-mail
let corpoEmail = dados.message;

// Se for HTML, usar como está, senão converter texto para HTML básico
let isHtml = dados.html || false;
if (!isHtml) {
  // Converter quebras de linha para HTML
  corpoEmail = corpoEmail
    .replace(/\n\n/g, '</p><p>')
    .replace(/\n/g, '<br>')
    .replace(/^/, '<p>')
    .replace(/$/, '</p>');
  isHtml = true;
}

// Adicionar assinatura padrão
const assinatura = `
<br><br>
<div style="border-top: 1px solid #ccc; padding-top: 10px; margin-top: 20px; font-size: 12px; color: #666;">
  <strong>Imobiliária</strong><br>
  📞 Telefone: (11) 99999-9999<br>
  📧 E-mail: contato@imobiliaria.com<br>
  🌐 Site: www.imobiliaria.com<br>
  📍 Endereço: Rua das Flores, 123 - São Paulo/SP
</div>
`;

corpoEmail += assinatura;

// Preparar dados para envio
const emailData = {
  to: dados.to,
  subject: assunto,
  message: corpoEmail,
  isHtml: isHtml,
  attachments: dados.attachments || [],
  replyTo: dados.reply_to || null,
  cc: dados.cc || null,
  bcc: dados.bcc || null
};

return {
  json: {
    email_data: emailData,
    original_request: dados
  }
};

// Gerar newsletter HTML personalizada
const clientes = $input.all().slice(0, -1); // Todos exceto o último
const imoveis = $input.last().json; // Último input são os imóveis

const newsletters = [];

for (const clienteItem of clientes) {
  const cliente = clienteItem.json;
  const nome = cliente.nome?.split(' ')[0] || 'Cliente';

  // Filtrar imóveis por preferências do cliente
  let imoveisFiltrados = imoveis;

  if (cliente.localizacao_preferida) {
    const localizacao = cliente.localizacao_preferida.toLowerCase();
    imoveisFiltrados = imoveis.filter(i => 
      i.bairro.toLowerCase().includes(localizacao) ||
      i.cidade.toLowerCase().includes(localizacao)
    );
  }

  if (cliente.valor_maximo) {
    imoveisFiltrados = imoveisFiltrados.filter(i => i.valor <= cliente.valor_maximo);
  }

  // Se não houver imóveis filtrados, usar os primeiros 3
  if (imoveisFiltrados.length === 0) {
    imoveisFiltrados = imoveis.slice(0, 3);
  } else {
    imoveisFiltrados = imoveisFiltrados.slice(0, 3);
  }

  // Gerar HTML dos imóveis
  const imoveisHtml = imoveisFiltrados.map(imovel => `
    <div style="border: 1px solid #ddd; border-radius: 8px; padding: 15px; margin: 10px 0; background: #f9f9f9;">
      <h3 style="color: #2c5aa0; margin: 0 0 10px 0;">${imovel.codigo_interno} - ${imovel.tipo}</h3>
      <p style="margin: 5px 0;"><strong>📍 Localização:</strong> ${imovel.endereco}, ${imovel.bairro}</p>
      <p style="margin: 5px 0;"><strong>💰 Valor:</strong> R$ ${imovel.valor.toLocaleString('pt-BR')}</p>
      <p style="margin: 5px 0;"><strong>🏠 Detalhes:</strong> ${imovel.quartos || 0} quartos, ${imovel.banheiros || 0} banheiros, ${imovel.area_construida || 0}m²</p>
      <p style="margin: 10px 0 0 0;">
        <a href="https://wa.me/5511999999999?text=Tenho interesse no imóvel ${imovel.codigo_interno}" 
           style="background: #25d366; color: white; padding: 8px 15px; text-decoration: none; border-radius: 5px; font-size: 14px;">
          💬 Tenho Interesse
        </a>
      </p>
    </div>
  `).join('');

  // Template da newsletter
  const newsletterHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Newsletter Imobiliária</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">

  <div style="text-align: center; background: linear-gradient(135deg, #2c5aa0 0%, #1e3a8a 100%); color: white; padding: 30px; border-radius: 10px; margin-bottom: 30px;">
    <h1 style="margin: 0; font-size: 28px;">🏠 Imobiliária</h1>
    <p style="margin: 10px 0 0 0; font-size: 16px;">Sua casa dos sonhos está aqui!</p>
  </div>

  <div style="margin-bottom: 30px;">
    <h2 style="color: #2c5aa0;">Olá, ${nome}! 👋</h2>
    <p>Esperamos que esteja tudo bem! Preparamos uma seleção especial de imóveis que podem interessar você.</p>
  </div>

  <div style="margin-bottom: 30px;">
    <h2 style="color: #2c5aa0; border-bottom: 2px solid #2c5aa0; padding-bottom: 10px;">🌟 Destaques da Semana</h2>
    ${imoveisHtml}
  </div>

  <div style="background: #f0f8ff; padding: 20px; border-radius: 8px; margin-bottom: 30px;">
    <h3 style="color: #2c5aa0; margin-top: 0;">💡 Dica da Semana</h3>
    <p>O mercado imobiliário está aquecido! É um ótimo momento para investir. Financiamentos estão com taxas atrativas.</p>
  </div>

  <div style="background: #e8f5e8; padding: 20px; border-radius: 8px; margin-bottom: 30px;">
    <h3 style="color: #2c5aa0; margin-top: 0;">🤝 Precisa de Ajuda?</h3>
    <p>Nossa equipe está sempre pronta para ajudar você a encontrar o imóvel ideal!</p>
    <p>
      <a href="https://wa.me/5511999999999" style="background: #25d366; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px; margin-right: 10px;">💬 WhatsApp</a>
      <a href="tel:+5511999999999" style="background: #2c5aa0; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;">📞 Ligar</a>
    </p>
  </div>

  <div style="text-align: center; border-top: 1px solid #ddd; padding-top: 20px; font-size: 12px; color: #666;">
    <p><strong>Imobiliária</strong></p>
    <p>📞 (11) 99999-9999 | 📧 contato@imobiliaria.com</p>
    <p>🌐 www.imobiliaria.com | 📍 Rua das Flores, 123 - São Paulo/SP</p>
    <p style="margin-top: 15px;">
      <a href="#" style="color: #666; text-decoration: none; font-size: 11px;">Descadastrar</a>
    </p>
  </div>

</body>
</html>
  `;

  newsletters.push({
    cliente_id: cliente.id,
    nome: cliente.nome,
    email: cliente.email,
    assunto: `${nome}, novidades incríveis da semana! 🏠✨`,
    conteudo_html: newsletterHtml,
    imoveis_incluidos: imoveisFiltrados.length
  });
}

return newsletters.map(newsletter => ({ json: newsletter }));
